text:
{
 "summary": {
  "es": "社会《しゃかい》のみんなにかかわることについて、とく・損《そん》や意見《いけん》のちがいを調整《ちょうせい》し、決《き》めて、行《おこな》うことを、政治《せいじ》とよびます。",
  "hs": "社会全体にかかわることについて、利害（とく・損）や意見の違《ちが》いを調整し、決定し、実行するはたらきを政治と呼びます。"
 },
 "blocks/0/text": {
  "es": "給料《きゅうりょう》から引《ひ》かれる所得税《しょとくぜい》が、1年《ねん》の収入《しゅうにゅう》がいくらからかかりはじめるかは、どこで決《き》まる？",
  "hs": "給料から引かれる所得税が、年収がいくらからかかり始めるかは、どこで決まる？"
 },
 "blocks/1/text": {
  "es": "税金《ぜいきん》・社会保障《しゃかいほしょう》・教育《きょういく》など、社会《しゃかい》のみんなにかかわる問題《もんだい》があります。それについて、ちがうとく・損《そん》や意見《いけん》を調整《ちょうせい》して決《き》め、決《き》めたことを行《おこな》うことが、政治《せいじ》です。",
  "hs": "税・社会保障・教育など社会全体にかかわる課題について、異なる利害や意見を調整して決定し、その決定を実行するはたらきが政治です。"
 },
 "blocks/2/text": {
  "es": "日本国《にほんこく》憲法《けんぽう》は、はじめの文《ぶん》（前文《ぜんぶん》）で、国民《こくみん》が「正当《せいとう》に選挙《せんきょ》された国会《こっかい》における代表者《だいひょうしゃ》を通《つう》じて行動《こうどう》」すると決《き》めています。選挙《せんきょ》で選《えら》んだ代表《だいひょう》が決《き》めるしくみ（間接《かんせつ》民主制《みんしゅせい》・代表《だいひょう》民主制《みんしゅせい》）が、基本《きほん》です。",
  "hs": "日本国憲法は前文で、国民が「正当に選挙された国会における代表者を通じて行動」すると定め、間接民主制（代表民主制、選んだ代表者に政治を任せるしくみ）を基本としています。"
 },
 "blocks/3/items/0": {
  "es": "法律《ほうりつ》・条例《じょうれい》（地方《ちほう》のきまり）をつくる",
  "hs": "法律・条例を制定する"
 },
 "blocks/3/items/1": {
  "es": "予算《よさん》を決《き》め、税金《ぜいきん》の使《つか》い道《みち》を決《き》める",
  "hs": "予算を議決し、税の使い道を決める"
 },
 "blocks/3/items/2": {
  "es": "条約《じょうやく》（国《くに》と国《くに》との約束《やくそく》）をむすぶ",
  "hs": "条約（国と国との約束）を結ぶ"
 },
 "blocks/3/items/3": {
  "es": "決《き》めたことを行《おこな》う（行政《ぎょうせい》）",
  "hs": "決定したことを実行する（行政）"
 },
 "blocks/4/text": {
  "es": "総務省《そうむしょう》は、選挙《せんきょ》で選《えら》ばれた代表《だいひょう》は「一部《いちぶ》の代表《だいひょう》としてではなく、すべての国民《こくみん》や住民《じゅうみん》のために政治《せいじ》を行《おこな》う」と説明《せつめい》しています。憲法《けんぽう》第《だい》15条《じょう》も、公務員《こうむいん》を「全体《ぜんたい》の奉仕者《ほうししゃ》」（みんなのために働《はたら》く人《ひと》）としています。",
  "hs": "総務省は、選挙で選ばれた代表者は「一部の代表としてではなく、すべての国民や住民のために政治を行う」と説明しています。憲法第15条も、公務員を「全体の奉仕者《ほうししゃ》」としています。"
 },
 "blocks/5/text": {
  "es": "どの政策《せいさく》がよいかは、何《なん》を大切《たいせつ》にするかの判断《はんだん》が入《はい》るため、意見《いけん》が分《わ》かれます。このサイトでは、事実《じじつ》と意見《いけん》を分《わ》け、意見《いけん》が分《わ》かれる点《てん》は、いくつかの見方《みかた》をならべます。",
  "hs": "どの政策が望ましいかは価値判断（何を大切にするかの判断）を含《ふく》むため、意見が分かれます。このサイトでは事実と意見を分け、意見が分かれる点は複数の視点を並べます。"
 }
}
